-- Arquivo de registros: topics and notes of a game, kept apart from games.state
-- (see docs/plans/ARQUIVO.md).
--
-- Unlike the game, members write here directly: the client runs the same pure
-- rules (src/systems/Archive.ts) and RLS keeps the master's notes ('mestre')
-- away from players, in reads, writes and realtime alike.

-- ---------------------------------------------------------------- tables

create table public.archive_topics (
  game_id uuid not null references public.games (id) on delete cascade,
  -- Generated by the client (newId), like every record created in game.
  id text not null check (id ~ '^[a-z0-9_-]{1,64}$'),
  name text not null check (char_length(btrim(name)) between 1 and 200),
  icon text check (char_length(icon) <= 16),
  position integer not null default 0,
  -- A character id, or 'mestre'.
  author_id text not null check (char_length(author_id) between 1 and 64),
  -- In the trash since; null while in use.
  deleted_at timestamptz,
  primary key (game_id, id)
);

create table public.archive_notes (
  game_id uuid not null,
  id text not null check (id ~ '^[a-z0-9_-]{1,64}$'),
  topic_id text not null,
  title text not null check (char_length(btrim(title)) between 1 and 200),
  body text not null default '' check (char_length(body) <= 20000),
  -- Game day the note records.
  day integer not null check (day >= 0),
  pinned boolean not null default false,
  visibility text not null check (visibility in ('todos', 'mestre')),
  position integer not null default 0,
  author_id text not null check (char_length(author_id) between 1 and 64),
  edited_by text check (char_length(edited_by) between 1 and 64),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (game_id, id),
  -- Emptying the trash removes a topic with the notes still in it.
  foreign key (game_id, topic_id) references public.archive_topics (game_id, id) on delete cascade
);

create index archive_notes_by_topic on public.archive_notes (game_id, topic_id);

-- ---------------------------------------------------------------- RLS

-- A player never reads nor writes the master's notes; members do everything else.
create function public.can_see_archive_note(target_game uuid, note_visibility text)
returns boolean
language sql
stable
set search_path = ''
as $$
  select public.is_member(target_game)
     and (note_visibility = 'todos' or public.is_master(target_game));
$$;

revoke execute on function public.can_see_archive_note(uuid, text) from public, anon;
grant execute on function public.can_see_archive_note(uuid, text) to authenticated;

alter table public.archive_topics enable row level security;
alter table public.archive_notes enable row level security;

create policy "members read the topics" on public.archive_topics
  for select to authenticated using (public.is_member(game_id));
create policy "members add topics" on public.archive_topics
  for insert to authenticated with check (public.is_member(game_id));
create policy "members edit topics" on public.archive_topics
  for update to authenticated
  using (public.is_member(game_id)) with check (public.is_member(game_id));
-- Removing is moving to the trash (an update); only emptying the trash deletes.
create policy "masters empty the trash of topics" on public.archive_topics
  for delete to authenticated using (public.is_master(game_id));

create policy "members read the notes they may see" on public.archive_notes
  for select to authenticated using (public.can_see_archive_note(game_id, visibility));
-- The check runs on the new row: a player cannot create a 'mestre' note nor turn one into it.
create policy "members add notes they may see" on public.archive_notes
  for insert to authenticated with check (public.can_see_archive_note(game_id, visibility));
create policy "members edit notes they may see" on public.archive_notes
  for update to authenticated
  using (public.can_see_archive_note(game_id, visibility))
  with check (public.can_see_archive_note(game_id, visibility));
create policy "masters empty the trash of notes" on public.archive_notes
  for delete to authenticated using (public.is_master(game_id));

revoke all on public.archive_topics, public.archive_notes from anon;
grant select, insert, update, delete on public.archive_topics, public.archive_notes to authenticated;

-- ---------------------------------------------------------------- rules RLS cannot see

-- A topic goes to the trash only when empty. security definer: it counts the
-- master's notes too, so a player is refused without seeing them. The message
-- is the client's error code.
create function public.archive_topic_must_be_empty()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.deleted_at is not null and old.deleted_at is null and exists (
    select 1 from public.archive_notes n
    where n.game_id = new.game_id and n.topic_id = new.id and n.deleted_at is null
  ) then
    raise exception 'category_not_empty' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

revoke execute on function public.archive_topic_must_be_empty() from public, anon, authenticated;

create trigger archive_topics_trash_only_empty
  before update of deleted_at on public.archive_topics
  for each row execute function public.archive_topic_must_be_empty();

-- Importing a save: the whole archive at once. Runs as the caller (RLS applies).
create function public.replace_archive(target_game uuid, topics jsonb, notes jsonb)
returns void
language plpgsql
set search_path = ''
as $$
begin
  if not public.is_master(target_game) then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  delete from public.archive_topics where game_id = target_game;

  insert into public.archive_topics (game_id, id, name, icon, position, author_id, deleted_at)
  select target_game, t.id, t.name, t.icon, t.position, t.author_id, t.deleted_at
  from jsonb_to_recordset(topics) as t (
    id text, name text, icon text, position integer, author_id text, deleted_at timestamptz
  );

  insert into public.archive_notes (
    game_id, id, topic_id, title, body, day, pinned, visibility, position,
    author_id, edited_by, created_at, updated_at, deleted_at
  )
  select target_game, n.id, n.topic_id, n.title, n.body, n.day, n.pinned, n.visibility, n.position,
         n.author_id, n.edited_by, n.created_at, n.updated_at, n.deleted_at
  from jsonb_to_recordset(notes) as n (
    id text, topic_id text, title text, body text, day integer, pinned boolean, visibility text,
    position integer, author_id text, edited_by text, created_at timestamptz,
    updated_at timestamptz, deleted_at timestamptz
  );
end;
$$;

revoke execute on function public.replace_archive(uuid, jsonb, jsonb) from public, anon;
grant execute on function public.replace_archive(uuid, jsonb, jsonb) to authenticated;

-- ---------------------------------------------------------------- realtime

-- Inserts and updates respect the RLS above. Deletes only carry the primary
-- key (default replica identity), so nothing of a removed note leaks.
alter publication supabase_realtime add table public.archive_topics, public.archive_notes;
